function sort(uint256[] memory arr) public pure returns (uint256[] memory) {
    for (uint256 i = 0; i < arr.length; i++) {
        uint256 key = arr[i];
        uint256 j = i - 1;
        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            j--;
        }
        arr[j + 1] = key;
    }
    return arr;
}

