function sort(uint256[] memory arr) public pure returns (uint256[] memory) {
    for (uint256 i = 1; i < arr.length; i++) {
        uint256 key = arr[i];
        uint256 j = i;
        while (j > 0 && arr[j - 1] > key) {
            arr[j] = arr[j - 1];
            j--;
        }
        arr[j] = key;
    }
    return arr;
}

