function countAtLeast(uint256[] calldata values, uint256 threshold)
    external pure returns (uint256 count)
{
    for (uint256 i = 0; i < values.length; i++) {
        if (values[i] >= threshold) count += 1;
    }
}

function insertionSort(uint256[] calldata values)
    external pure returns (uint256[] memory result)
{
    result = values;
    for (uint256 i = 1; i < result.length; i++) {
        uint256 key = result[i];
        uint256 j = i;
        while (j > 0 && result[j - 1] > key) {
            result[j] = result[j - 1];
            j--;
        }
        result[j] = key;
    }
}
